-- Enable UUID extension
create extension if not exists "uuid-ossp";

-- ============================================================================
-- 1. ADMIN USERS (extends Supabase Auth)
-- ============================================================================
create table if not exists public.admin_users (
  id uuid references auth.users(id) on delete cascade primary key,
  email text unique not null,
  full_name text,
  role text default 'admin',
  created_at timestamptz default now()
);

-- ============================================================================
-- 2. PRODUCTS
-- ============================================================================
create table if not exists public.products (
  id text primary key,
  name_en text not null,
  name_ar text,
  slug text unique,
  category text not null,
  brand_slug text not null,
  description_en text,
  description_ar text,
  price numeric not null default 0,
  sale_price numeric,
  discount_pct numeric default 0,
  active boolean default true,
  featured boolean default false,
  new_arrival boolean default false,
  hero_product boolean default false,
  stock integer default 0,
  sku text,
  key_shapes jsonb default '[]'::jsonb,
  images text[] default '{}',
  main_image text,
  fitment jsonb default '{}'::jsonb,
  "order" integer default 0,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- ============================================================================
-- 3. CATEGORIES
-- ============================================================================
create table if not exists public.categories (
  id text primary key,
  name_en text not null,
  name_ar text,
  slug text unique,
  description_en text,
  description_ar text,
  image text,
  active boolean default true,
  icon text,
  product_count integer default 0,
  "order" integer default 0,
  created_at timestamptz default now()
);

-- ============================================================================
-- 4. BRANDS
-- ============================================================================
create table if not exists public.brands (
  id text primary key,
  name_en text not null,
  name_ar text,
  slug text unique not null,
  description_en text,
  description_ar text,
  logo text,
  emblem text,
  active boolean default true,
  product_count integer default 0,
  "order" integer default 0,
  created_at timestamptz default now()
);

-- ============================================================================
-- 5. BUNDLES / PACKAGES
-- ============================================================================
create table if not exists public.bundles (
  id text primary key,
  brand_slug text not null,
  name_en text,
  name_ar text,
  active boolean default true,
  bundle_price numeric not null default 0,
  normal_total numeric default 0,
  key_case_id text,
  key_holder_id text,
  medal_id text,
  "order" integer default 0,
  created_at timestamptz default now()
);

-- ============================================================================
-- 6. ORDERS
-- ============================================================================
create table if not exists public.orders (
  id text primary key,
  created_at timestamptz default now(),
  customer jsonb not null,
  items jsonb not null,
  subtotal numeric default 0,
  bundle_discount numeric default 0,
  delivery_fee numeric default 0,
  total numeric default 0,
