  ($q$p_toyota_holder$q$, $q$Spinto Signature Metal Key Holder — Toyota$q$, $q$حامل مفاتيح معدني مميز — تويوتا$q$, $q$toyota-signature-metal-key-holder$q$, $q$keyholder$q$, $q$toyota$q$, $q$A sculptural signature holder machined from champagne-gold alloy for the Toyota. The secure silicone core keeps your key snug while the precision clasp lets you carry it on your belt or in your bag.$q$, $q$حامل مميز مصنوع من سبيكة ذهبية شامبين مصقولة لسيارة تويوتا. يضم القلب السيليكوني الآمن مفتاحك بإحكام بينما يسمح لك المشبك الدقيق بحمله على حزامك أو في حقيبتك.$q$, $q$Machined champagne-gold alloy with a secure silicone core.$q$, $q$سبيكة ذهبية مصقولة مع قلب سيليكون آمن.$q$, $q$Alloy, silicone$q$, $q$سبيكة، سيليكون$q$, 800, NULL, 880, 9, true, false, false, false, true, false, false, false, 20, NULL, $q$[{"shape":"A","available":true},{"shape":"B","available":true},{"shape":"C","available":true},{"shape":"D","available":false}]$q$::jsonb, array[$q$/img/asset.svg?type=keyholder&brand=toyota$q$, $q$/img/asset.svg?type=detail-a&brand=toyota$q$, $q$/img/asset.svg?type=detail-b&brand=toyota$q$]::text[], $q$/img/asset.svg?type=keyholder&brand=toyota$q$, $q${}$q$::jsonb, 7.75, $q$1-year warranty$q$, $q$ضمان سنة$q$, $q$Signature$q$, $q$مميز$q$, $q$["Corolla","Camry","Land Cruiser"]$q$::jsonb, $q$[2021,2022,2023,2024]$q$::jsonb, $q$[{"label_en":"Material","label_ar":"الخامة","value_en":"Alloy, silicone","value_ar":"سبيكة، سيليكون"},{"label_en":"Warranty","label_ar":"الضمان","value_en":"1-year warranty","value_ar":"ضمان سنة"},{"label_en":"Brand","label_ar":"الماركة","value_en":"Toyota","value_ar":"تويوتا"},{"label_en":"Category","label_ar":"الفئة","value_en":"keyholder","value_ar":"keyholder"}]$q$::jsonb, $q$[{"brand":"toyota","model":"Corolla","year":2021},{"brand":"toyota","model":"Corolla","year":2022},{"brand":"toyota","model":"Corolla","year":2023},{"brand":"toyota","model":"Corolla","year":2024},{"brand":"toyota","model":"Camry","year":2021},{"brand":"toyota","model":"Camry","year":