  ($q$p_honda_medal$q$, $q$Honda Medal — Black & Gold$q$, $q$ميدالية هوندا — أسود وذهبي$q$, $q$honda-medal-black-gold$q$, $q$medal$q$, $q$honda$q$, $q$The Spinto Honda collector Medal is finished in deep black and champagne gold. Machined as a refined emblem, it is the perfect finishing touch for enthusiasts who appreciate detail.$q$, $q$ميدالية سبينتو لسيارة هوندا بتشطيب أسود عميق وذهبي شامبين. مصممة كشارة راقية، وهي اللمسة النهائية المثالية لعشاق التفاصيل الدقيقة.$q$, $q$A refined collector emblem finished in black and champagne gold.$q$, $q$شارة راقية للجمع بتشطيب أسود وذهبي شامبين.$q$, $q$Alloy, black & gold$q$, $q$سبيكة، أسود وذهبي$q$, 500, NULL, 560, 11, true, false, false, false, true, true, false, false, 30, NULL, $q$[{"shape":"A","available":true},{"shape":"B","available":false},{"shape":"C","available":true},{"shape":"D","available":false}]$q$::jsonb, array[$q$/img/asset.svg?type=medal&brand=honda$q$, $q$/img/asset.svg?type=detail-a&brand=honda$q$, $q$/img/asset.svg?type=detail-b&brand=honda$q$]::text[], $q$/img/asset.svg?type=medal&brand=honda$q$, $q${}$q$::jsonb, 12.25, $q$1-year warranty$q$, $q$ضمان سنة$q$, $q$Black & Gold$q$, $q$أسود وذهبي$q$, $q$["Civic","Accord","CR-V"]$q$::jsonb, $q$[2021,2022,2023,2024]$q$::jsonb, $q$[{"label_en":"Material","label_ar":"الخامة","value_en":"Alloy, black & gold","value_ar":"سبيكة، أسود وذهبي"},{"label_en":"Warranty","label_ar":"الضمان","value_en":"1-year warranty","value_ar":"ضمان سنة"},{"label_en":"Brand","label_ar":"الماركة","value_en":"Honda","value_ar":"هوندا"},{"label_en":"Category","label_ar":"الفئة","value_en":"medal","value_ar":"medal"}]$q$::jsonb, $q$[{"brand":"honda","model":"Civic","year":2021},{"brand":"honda","model":"Civic","year":2022},{"brand":"honda","model":"Civic","year":2023},{"brand":"honda","model":"Civic","year":2024},{"brand":"honda","model":"Accord","year":2021},{"brand":"honda","model":"Accord","year":2022},{"brand":"honda","model":"Accord","year":2023},{"brand":"honda","model":"Accord","year