  ($q$p_ferrari_holder$q$, $q$Spinto Signature Metal Key Holder — Ferrari$q$, $q$حامل مفاتيح معدني مميز — فيراري$q$, $q$ferrari-signature-metal-key-holder$q$, $q$keyholder$q$, $q$ferrari$q$, $q$A sculptural signature holder machined from champagne-gold alloy for the Ferrari. The secure silicone core keeps your key snug while the precision clasp lets you carry it on your belt or in your bag.$q$, $q$حامل مميز مصنوع من سبيكة ذهبية شامبين مصقولة لسيارة فيراري. يضم القلب السيليكوني الآمن مفتاحك بإحكام بينما يسمح لك المشبك الدقيق بحمله على حزامك أو في حقيبتك.$q$, $q$Machined champagne-gold alloy with a secure silicone core.$q$, $q$سبيكة ذهبية مصقولة مع قلب سيليكون آمن.$q$, $q$Alloy, silicone$q$, $q$سبيكة، سيليكون$q$, 850, NULL, 930, 9, true, false, false, false, true, false, false, false, 20, NULL, $q$[{"shape":"A","available":true},{"shape":"B","available":true},{"shape":"C","available":true},{"shape":"D","available":false}]$q$::jsonb, array[$q$/img/asset.svg?type=keyholder&brand=ferrari$q$, $q$/img/asset.svg?type=detail-a&brand=ferrari$q$, $q$/img/asset.svg?type=detail-b&brand=ferrari$q$]::text[], $q$/img/asset.svg?type=keyholder&brand=ferrari$q$, $q${}$q$::jsonb, 17.75, $q$1-year warranty$q$, $q$ضمان سنة$q$, $q$Signature$q$, $q$مميز$q$, $q$["F8","Roma","SF90"]$q$::jsonb, $q$[2021,2022,2023,2024]$q$::jsonb, $q$[{"label_en":"Material","label_ar":"الخامة","value_en":"Alloy, silicone","value_ar":"سبيكة، سيليكون"},{"label_en":"Warranty","label_ar":"الضمان","value_en":"1-year warranty","value_ar":"ضمان سنة"},{"label_en":"Brand","label_ar":"الماركة","value_en":"Ferrari","value_ar":"فيراري"},{"label_en":"Category","label_ar":"الفئة","value_en":"keyholder","value_ar":"keyholder"}]$q$::jsonb, $q$[{"brand":"ferrari","model":"F8","year":2021},{"brand":"ferrari","model":"F8","year":2022},{"brand":"ferrari","model":"F8","year":2023},{"brand":"ferrari","model":"F8","year":2024},{"brand":"ferrari","model":"Roma","year":2021},{"brand":"ferrari","model":"Roma","year":2022},{"brand":"fer